    pubkey: Option<&str>,
    trace_id: Option<&str>,
    request_footprint: &str,
) -> Option<Result<String, Status>> {
    let engine = ENGINE.read().expect("engine lock poisoned").clone()?;
    let session_id = pubkey.map(op_identity::session::derive_session_id);
    let args = match (&session_id, trace_id) {
        (Some(sid), _) => serde_json::json!({ "session_id": sid }),
        (None, Some(trace)) => serde_json::json!({ "trace_id": trace }),
        (None, None) => return None,
    };

    let result = tokio::task::block_in_place(|| {
        tokio::runtime::Handle::current().block_on(
            crate::identity_sled_dispatch::dispatch_identity_sled_method(
                engine.as_ref(),
                "get_identity",
                &args,
            ),
        )
    });

    let identity = match result {
        Ok(value) => value.get("identity").cloned()?,
        Err(_) => return None,
    };
    // `genesis` is the authoritative verdict (Task 7); `hashed_footprint` is
    // retained only as a transitional fallback for pre-migration records that
    // have not yet been re-keyed. Either match is accepted, and a missing
    // stored value fails closed via the `?` above.
    let stored = identity
        .get("genesis")
        .or_else(|| identity.get("hashed_footprint"))
        .and_then(|v| v.as_str())
        .map(str::to_string);
    let stored = match stored {
        Some(s) => s,
        None => return None,
    };
    let expires_at = identity.get("expires_at").and_then(|v| v.as_i64());

    if let Some(expires_at) = expires_at {
        if expires_at != 0 && expires_at <= chrono::Utc::now().timestamp() {
            return Some(Err(Status::permission_denied(
                "Identity term has expired. Re-authenticate to renew.",
            )));
        }
    }

    if stored != request_footprint {
        return None;
    }

    let resolved_session_id = identity
        .get("session_id")
        .and_then(|v| v.as_str())
        .map(str::to_string)
        .or(session_id)?;
    Some(Ok(resolved_session_id))
}

