// Auto-provision the host's own session identity so the interceptor
// recognises the sled footprint immediately after a reseal / cold start.
if let Some(host_sid) = crate::identity_sled_dispatch::host_session_id() {
    let pubkey = std::env::var("WG_PUBKEY").unwrap_or_default();
    if !pubkey.is_empty() {
        match mutation_engine.mint_and_store_genesis(&host_sid, &pubkey).await {
            Ok(genesis) => {
                tracing::info!(
                    session_id = %host_sid,
                    genesis = %genesis,
                    "host session genesis minted at startup"
                );
                // Write the genesis back into the sled's hashed_footprint
                // field so /api/identity/sled returns the value the
                // interceptor expects in x-ghostbridge-footprint.
                if let Ok(genesis_bytes) = hex::decode(&genesis) {
                    if let Ok(fp) = <[u8; 32]>::try_from(genesis_bytes.as_slice()) {
                        if let Ok((ptr, _mmap)) = op_identity::schema_bridge::read_sled() {
                            let mut sled = unsafe { *ptr };
                            sled.hashed_footprint = fp;
                            if let Err(e) = op_identity::schema_bridge::write_sled(&sled) {
                                tracing::warn!(%e, "failed to write genesis into sled footprint field");
                            }
                        }
                    }
                }
            }
            Err(error) => tracing::warn!(
                %error,
                session_id = %host_sid,
                "host session genesis mint failed; browser identity may be rejected"
            ),
        }
    }
}

